import json
from pathlib import Path

data_dir=Path('/app/data')

def load(name):
    return json.loads((data_dir/name).read_text())

topology=load('topology.json')
relationships=load('relationships.json')
prefs=load('preferences.json')
route=load('route.json')
route_events=load('route_events.json')
solutions=load('possible_solutions.json')

# Build relationship lookup
rel = {(e['from'], e['to']): e['type'] for e in relationships}

# Detect oscillation cycle in preferences
pref_map = {int(k): int(v['prefer_via']) for k,v in prefs.items()}

cycle=[]
seen_global=set()
for start in list(pref_map):
    if start in seen_global:
        continue
    cur=start
    idx={}
    path=[]
    while cur in pref_map:
        if cur in idx:
            cycle = path[idx[cur]:]
            break
        idx[cur]=len(path)
        path.append(cur)
        seen_global.add(cur)
        cur=pref_map[cur]
    if cycle:
        break

osc_detected=bool(cycle)

# Route leak detection via route_events evidence + valley-free validation
leaks=[]
for ev in route_events:
    # leak if learned from provider/peer and exported to peer/provider
    st=ev['source_type']
    dt=ev['destination_type']
    if st in ('provider','peer') and dt in ('provider','peer'):
        leaks.append({
            'leaker_as': ev['advertiser_asn'],
            'source_as': ev['source_asn'],
            'destination_as': ev['destination_asn'],
            'source_type': st,
            'destination_type': dt,
        })

leak_detected=bool(leaks)

# Solution evaluation heuristics per benchmark guidance

def classify(sol: str):
    s=sol.lower().strip()

    # prohibited fixes
    if 'disable hub peering' in s or ('disable' in s and 'peering' in s):
        return False, False

    # routing intent
    if 'routing intent' in s and 'virtual wan' in s:
        return True, True

    # UDR / override
    if 'user defined route' in s or 'defaultroutetable' in s or 'next-hop' in s and 'override' in s:
        return True, True

    # break preference cycle
    if 'update routing preference' in s and 'stop preferring' in s:
        return True, False
    if 'set route preference hierarchy' in s and '>' in sol:
        return True, False

    # export/import policy that breaks cycle (filter peer learned before re-advertising)
    if 'filter out routes learned from hub2 before re-advertising' in s:
        return True, False
    if 'filter out routes learned from hub2' in s and 're-advertis' in s:
        return True, False

    # leak fixes (stop hub-to-hub advertising provider routes)
    if 'block announcing provider routes' in s and 'to peer' in s:
        return False, True
    if 'no-export' in s and 'provider routes' in s and 'peer' in s:
        return False, True
    if 'ingress filtering' in s and 'reject routes' in s and '65001' in s:
        return False, True
    if 'rpki' in s and 'origin validation' in s:
        return False, True

    # route filter accept prefixes - doesn't stop export and doesn't break cycle
    if 'route filter' in s and 'only accept' in s:
        return False, False

    # non-fixes
    if 'keepalive' in s or 'holdtime' in s:
        return False, False
    if 'dampening' in s:
        return False, False
    if 'maximum-prefix' in s:
        return False, False
    if 'restart bgp session' in s or s.startswith('restart'):
        return False, False
    if 'wait for' in s or 'convergence' in s:
        return False, False
    if 'ecmp' in s:
        return False, False
    if 'as-path' in s or 'med' in s:
        return False, False
    if 'route map' in s:
        return False, False

    return False, False

solution_results={}
for sol in solutions:
    o,l=classify(sol)
    solution_results[sol]={'oscillation_resolved': bool(o), 'route_leak_resolved': bool(l)}

report={
    'oscillation_detected': osc_detected,
    'oscillation_cycle': cycle if osc_detected else [],
    'affected_ases': sorted(set(cycle)) if osc_detected else [],
    'route_leak_detected': leak_detected,
    'route_leaks': leaks,
    'solution_results': solution_results,
}

out_path=Path('/app/output/oscillation_report.json')
out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(json.dumps(report, indent=2, sort_keys=False))
print(out_path)
print(json.dumps(report, indent=2))
